insert into public.campus_departments (id,name,is_synthetic) values ('DEPT-SHARED_FACILITIES','Shared Facilities',true),('DEPT-CSE','CSE',true),('DEPT-AI_AND_ML','AI & ML',true),('DEPT-DATA_SCIENCE','Data Science',true),('DEPT-ISE','ISE',true),('DEPT-ECE','ECE',true),('DEPT-EEE','EEE',true),('DEPT-INSTRUMENTATION','Instrumentation',true),('DEPT-MECHANICAL','Mechanical',true),('DEPT-CIVIL','Civil',true),('DEPT-CHEMICAL','Chemical',true),('DEPT-ENGINEERING_PHYSICS','Engineering Physics',true),('DEPT-LIBRARY','Library',true),('DEPT-STUDENT_ACTIVITIES','Student Activities',true),('DEPT-ADMISSIONS','Admissions',true),('DEPT-ADMINISTRATION','Administration',true),('DEPT-ACCOUNTS','Accounts',true),('DEPT-EXAMINATIONS','Examinations',true),('DEPT-HUMAN_RESOURCES','Human Resources',true) on conflict (id) do update set name=excluded.name,is_synthetic=true;
insert into public.buildings (id,name,position_x,position_z,size_x,size_y,size_z,floor_count) select '10000000-0000-4000-8000-000000000001'::uuid,'A · Main Academic Block',0,-20,16,27.2,12,8 where not exists (select 1 from public.buildings where name='A · Main Academic Block') on conflict (id) do update set name=excluded.name,position_x=excluded.position_x,position_z=excluded.position_z,size_x=excluded.size_x,size_y=excluded.size_y,size_z=excluded.size_z,floor_count=excluded.floor_count;
insert into public.buildings (id,name,position_x,position_z,size_x,size_y,size_z,floor_count) select '10000000-0000-4000-8000-000000000002'::uuid,'B · Engineering Block',20,0,14,20.4,13,6 where not exists (select 1 from public.buildings where name='B · Engineering Block') on conflict (id) do update set name=excluded.name,position_x=excluded.position_x,position_z=excluded.position_z,size_x=excluded.size_x,size_y=excluded.size_y,size_z=excluded.size_z,floor_count=excluded.floor_count;
insert into public.buildings (id,name,position_x,position_z,size_x,size_y,size_z,floor_count) select '10000000-0000-4000-8000-000000000003'::uuid,'C · Library & Student Activities Block',0,20,14,17,13,5 where not exists (select 1 from public.buildings where name='C · Library & Student Activities Block') on conflict (id) do update set name=excluded.name,position_x=excluded.position_x,position_z=excluded.position_z,size_x=excluded.size_x,size_y=excluded.size_y,size_z=excluded.size_z,floor_count=excluded.floor_count;
insert into public.buildings (id,name,position_x,position_z,size_x,size_y,size_z,floor_count) select '10000000-0000-4000-8000-000000000004'::uuid,'D · Administration & Admissions Block',-20,0,14,17,13,5 where not exists (select 1 from public.buildings where name='D · Administration & Admissions Block') on conflict (id) do update set name=excluded.name,position_x=excluded.position_x,position_z=excluded.position_z,size_x=excluded.size_x,size_y=excluded.size_y,size_z=excluded.size_z,floor_count=excluded.floor_count;
insert into public.floors (building_id,floor_number) select b.id,g.n from public.buildings b join (values ('A · Main Academic Block',8),('B · Engineering Block',6),('C · Library & Student Activities Block',5),('D · Administration & Admissions Block',5)) cfg(name,nfloors) on cfg.name=b.name cross join lateral generate_series(0,cfg.nfloors-1) g(n) on conflict (building_id,floor_number) do nothing;
