begin;

create table if not exists public.campus_departments (id text primary key, name text not null unique, is_synthetic boolean not null default true);


alter table public.rooms add column if not exists campus_room_code text;

alter table public.rooms add column if not exists department_id text references public.campus_departments(id);

alter table public.rooms add column if not exists area_m2 numeric check (area_m2 is null or area_m2 > 0);

alter table public.rooms add column if not exists capacity integer check (capacity is null or capacity >= 0);

alter table public.rooms add column if not exists operating_schedule text;

alter table public.rooms add column if not exists is_synthetic boolean not null default false;

create unique index if not exists rooms_campus_room_code_idx on public.rooms(campus_room_code) where campus_room_code is not null;

alter table public.floors drop constraint if exists floors_floor_number_check; alter table public.floors add constraint floors_floor_number_check check (floor_number between 0 and 100);

alter table public.floors drop constraint if exists floors_building_id_floor_number_key;

update public.floors f set floor_number=f.floor_number-1 from public.buildings b where b.id=f.building_id and f.floor_number between 1 and 100 and not exists (select 1 from public.floors g where g.building_id=b.id and g.floor_number=0) and (b.name in ('Admin Building','Hostel A','Library','Science Block','1','2','3','4') or b.id in ('10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000004'));

