create table if not exists public.campus_energy_equipment (id text primary key, room_id uuid not null references public.rooms(id) on delete cascade, name text not null, category text not null, quantity integer not null check(quantity>0), rated_watts_each numeric not null check(rated_watts_each>0), operating_hours_per_day numeric not null check(operating_hours_per_day between 0 and 24), operating_window text not null, standby_watts_each numeric not null default 0 check(standby_watts_each>=0), load_factor numeric not null check(load_factor between 0 and 1), operating_state text not null, is_essential boolean not null default false, is_permanently_installed boolean not null default true, is_synthetic boolean not null default true);

alter table public.campus_energy_equipment add column if not exists operating_window text not null default '09:00-16:00';

create index if not exists campus_energy_equipment_room_idx on public.campus_energy_equipment(room_id);

create table if not exists public.campus_energy_sessions (id text primary key, room_id uuid not null references public.rooms(id) on delete cascade, day_of_week text not null, start_hour integer not null check(start_hour between 0 and 23), end_hour integer not null check(end_hour between 1 and 24), activity text not null, department_id text references public.campus_departments(id), student_group text not null, expected_attendance integer not null check(expected_attendance>=0), room_capacity integer not null check(room_capacity>=expected_attendance), session_type text not null, source text not null default 'synthetic', check(end_hour>start_hour));

alter table public.campus_energy_sessions add column if not exists student_group text not null default 'unassigned';

create index if not exists campus_energy_sessions_room_idx on public.campus_energy_sessions(room_id,day_of_week,start_hour);

create table if not exists public.campus_occupancy_intervals (id text primary key, session_id text references public.campus_energy_sessions(id) on delete cascade, room_id uuid not null references public.rooms(id) on delete cascade, day_of_week text not null, start_hour integer not null check(start_hour between 0 and 23), end_hour integer not null check(end_hour between 1 and 24), scheduled_occupancy integer not null check(scheduled_occupancy>=0), simulated_occupancy integer not null check(simulated_occupancy>=0), room_capacity integer not null check(simulated_occupancy<=room_capacity and scheduled_occupancy<=room_capacity), source text not null default 'synthetic');

create index if not exists campus_occupancy_room_idx on public.campus_occupancy_intervals(room_id,day_of_week,start_hour);

alter table public.campus_departments enable row level security; alter table public.campus_energy_equipment enable row level security; alter table public.campus_energy_sessions enable row level security; alter table public.campus_occupancy_intervals enable row level security;

grant select on public.campus_departments to authenticated;

drop policy if exists "Verified campus users read campus_departments" on public.campus_departments;

create policy "Verified campus users read campus_departments" on public.campus_departments for select to authenticated using (auth.jwt()->'app_metadata'->>'role' in ('student','worker','admin') or exists (select 1 from public.campus_profiles p where p.user_id=auth.uid() and p.verification_status='verified' and p.role in ('student','worker','admin')));

grant select on public.campus_energy_equipment to authenticated;

drop policy if exists "Verified campus users read campus_energy_equipment" on public.campus_energy_equipment;

create policy "Verified campus users read campus_energy_equipment" on public.campus_energy_equipment for select to authenticated using (auth.jwt()->'app_metadata'->>'role' in ('student','worker','admin') or exists (select 1 from public.campus_profiles p where p.user_id=auth.uid() and p.verification_status='verified' and p.role in ('student','worker','admin')));

grant select on public.campus_energy_sessions to authenticated;

drop policy if exists "Verified campus users read campus_energy_sessions" on public.campus_energy_sessions;

create policy "Verified campus users read campus_energy_sessions" on public.campus_energy_sessions for select to authenticated using (auth.jwt()->'app_metadata'->>'role' in ('student','worker','admin') or exists (select 1 from public.campus_profiles p where p.user_id=auth.uid() and p.verification_status='verified' and p.role in ('student','worker','admin')));

grant select on public.campus_occupancy_intervals to authenticated;

drop policy if exists "Verified campus users read campus_occupancy_intervals" on public.campus_occupancy_intervals;

create policy "Verified campus users read campus_occupancy_intervals" on public.campus_occupancy_intervals for select to authenticated using (auth.jwt()->'app_metadata'->>'role' in ('student','worker','admin') or exists (select 1 from public.campus_profiles p where p.user_id=auth.uid() and p.verification_status='verified' and p.role in ('student','worker','admin')));




commit;
